m text-slate-700">Precio unitario</label><input name="details[__INDEX__][unit_price]" type="number" min="0" step="0.01" class="concept-price mt-1 block w-full rounded-lg border-slate-300"></div><div class="flex items-end"><button type="button" class="remove-detail w-full rounded-lg border border-red-300 px-3 py-2 text-sm font-semibold text-red-700 hover:bg-red-50">Quitar</button></div></div></div></template>
    <script>
        const details = document.getElementById('details');
        const template = document.getElementById('detail-template');
        const clientSelect = document.getElementById('client_id');
        const referralCreditInput = document.getElementById('referral_credit_amount');
        const availableReferralCredit = document.getElementById('available-referral-credit');
        let nextIndex = {{ count($details) }};

        function configureRow(row) { row.querySelector('[data-item-selector]').addEventListener('change', (event) => { const option = event.target.selectedOptions[0]; if (!option.value) return; row.querySelector('.concept-type').value = option.dataset.type; row.querySelector('.concept-reference').value = option.value; row.querySelector('.concept-description').value = option.dataset.name; row.querySelector('.concept-price').value = option.dataset.price; }); row.querySelector('.remove-detail').addEventListener('click', () => row.remove()); }
        function refreshReferralCredit() { const credit = Number(clientSelect.selectedOptions[0]?.dataset.referralCredit || 0); referralCreditInput.max = credit; availableReferralCredit.textContent = clientSelect.value ? `Saldo disponible: Q${credit.toFixed(2)}` : 'Selecciona un cliente para consultar su saldo disponible.'; }
        document.querySelectorAll('.detail-row').forEach(configureRow); clientSelect.addEventListener('change', refreshReferralCredit); refreshReferralCredit();
        document.getElementById('add-detail').addEventListener('click', () => { const fragment = template.content.cloneNode(true); const row = fragment.querySelector('.detail-row'); row.innerHTML = row.innerHTML.replaceAll('__INDEX__', nextIndex++); details.appendChild(row); configureRow(row); });
    </script>
